# For each cell in output, find which input colored cell is closest

colored_cells = []
for r in range(21):
    for c in range(12):
        val = test_input[r][c]
        if val != 2:
            colored_cells.append((r, c, val))

print(f"Colored cells: {colored_cells}")

def manhattan_dist(p1, p2):
    return abs(p1[0] - p2[0]) + abs(p1[1] - p2[1])

output = []
for r in range(21):
    for c in range(12):
        # Find closest colored cell
        closest = None
        min_dist = float('inf')
        closest_val = 2  # default background
        for cr, cc, cval in colored_cells:
            dist = manhattan_dist((r, c), (cr, cc))
            if dist < min_dist:
                min_dist = dist
                closest = (cr, cc, cval)
                closest_val = cval
        output.append(closest_val)

# Convert to 2D list
output_2d = []
idx = 0
for r in range(21):
    output_2d.append(output[idx:idx+12])
    idx += 12

print("Voronoi output:")
for row in output_2d:
    print(row)

